mapper.select:
SELECT target_contract_count
FROM sales_monthly_target
WHERE sales_user_id = #{salesUserId}
  AND target_year_month = #{yearMonth}

SELECT COUNT(id)
FROM contract
WHERE sales_user_id = #{salesUserId}
  AND DATE_FORMAT(updated_at, '%Y-%m') = #{yearMonth}
  AND contract_status_code = '06'
  AND contract_result_status_code = '02'

SELECT COUNT(id)
FROM contract
WHERE sales_user_id = #{salesUserId}
  AND YEAR(updated_at) = #{year}
  AND contract_status_code = '06'
  AND contract_result_status_code = '02'

WITH BranchRankings AS (
    SELECT
        su.id AS sales_user_id,
        ROW_NUMBER() OVER (
            ORDER BY COUNT(c.id) DESC, su.name ASC
            ) AS `rank`
    FROM sales_user su
             LEFT JOIN contract c ON su.id = c.sales_user_id
        AND DATE_FORMAT(c.updated_at, '%Y-%m') = #{yearMonth}
        AND c.contract_status_code = '06'
        AND c.contract_result_status_code = '02'
    WHERE su.branch_id = #{branchId}
      AND su.status_code = '01'
    GROUP BY su.id, su.name
)
SELECT `rank` FROM BranchRankings WHERE sales_user_id = #{salesUserId}

